1	// SPDX-License-Identifier: Apache-2.0
2	//! Rust models of how client SDKs turn stream bytes into tool calls (spec § 8.1).
3	//!
4	//! The models read the interceptor's OUTPUT. Each one reproduces its SDK's SSE decoder and its
5	//! accumulation rules, including the quirks that made the canonical form necessary (spec D9).
6	//!
7	//! A model runs to the end of the stream or to the first point where its SDK raises
8	//! (`Run::error`). `Run::calls` is the client's snapshot at that point. The SDKs surface calls
9	//! while they stream, before any final result: openai-python and openai-node fire
10	//! `tool_calls.function.arguments.done` events, and LangChain yields `tool_call_chunks`. So a
11	//! client can act on a call before its SDK raises, and the snapshot at a raise is checked too
12	//! ([`check_i1`]).
13	//!
14	//! JSON is parsed with serde_json in every model. serde_json and all four SDKs keep the last of
15	//! two duplicate keys. serde_json rejects `NaN`, which Python's `json` accepts, so a Python model
16	//! raises on a record its SDK would read; that only makes a model stricter, never more lenient.
17	
18	use std::collections::BTreeMap;
19	
20	use paigasus_gateway_core::{Decision, Format, ToolCall, ToolCallKind};
21	use serde_json::{Map, Value, json};
22	
23	/// One tool call a client would run.
24	#[derive(Debug, Clone, PartialEq, Eq)]
25	pub struct ModelCall {
26	    /// The choice the client attributes the call to. Always 0 for Anthropic and LangChain.
27	    pub choice: u32,
28	    /// `function`, `custom`, `legacy`, `tool_use`, or `other`.
29	    pub kind: &'static str,
30	    pub name: String,
31	    /// The raw argument string, or, when `parsed`, the compact JSON of the value the client parsed
32	    /// from it (anthropic-python's `input`, LangChain's `args`).
33	    pub arguments: String,
34	    pub parsed: bool,
35	}
36	
37	/// What one client derives from a byte stream.
38	#[derive(Debug, Clone, Default)]
39	pub struct Run {
40	    pub calls: Vec<ModelCall>,
41	    /// `Some` when the SDK raises. `calls` then holds the snapshot at that point.
42	    pub error: Option<String>,
43	}
44	
45	pub type Model = fn(&[u8]) -> Result<Vec<ModelCall>, String>;
46	pub type Runner = fn(&[u8]) -> Run;
47	
48	fn result(r: Run) -> Result<Vec<ModelCall>, String> {
49	    match r.error {
50	        Some(e) => Err(e),
51	        None => Ok(r.calls),
52	    }
53	}
54	
55	fn openai_python(b: &[u8]) -> Result<Vec<ModelCall>, String> {
56	    result(run_openai_python(b))
57	}
58	fn openai_node(b: &[u8]) -> Result<Vec<ModelCall>, String> {
59	    result(run_openai_node(b))
60	}
61	fn langchain(b: &[u8]) -> Result<Vec<ModelCall>, String> {
62	    result(run_langchain(b))
63	}
64	fn anthropic_python(b: &[u8]) -> Result<Vec<ModelCall>, String> {
65	    result(run_anthropic_python(b))
66	}
