68	/// Every model. openai-node raises on an Anthropic stream (it iterates `chunk.choices`), so pair
69	/// models with the stream format through [`runners`] where that matters.
70	pub const MODELS: &[(&str, Model)] = &[
71	    ("openai-python", openai_python),
72	    ("openai-node", openai_node),
73	    ("langchain", langchain),
74	    ("anthropic-python", anthropic_python),
75	];
