77	const OPENAI_RUNNERS: &[(&str, Runner)] = &[("openai-python", run_openai_python), ("openai-node", run_openai_node), ("langchain", run_langchain)];
78	const ANTHROPIC_RUNNERS: &[(&str, Runner)] = &[("anthropic-python", run_anthropic_python)];
