80	/// The models of the clients that read `format`.
81	pub fn runners(format: Format) -> &'static [(&'static str, Runner)] {
82	    match format {
83	        Format::AnthropicMessages => ANTHROPIC_RUNNERS,
84	        _ => OPENAI_RUNNERS,
85	    }
