88	/// The model kind of a decided call.
89	pub fn kind_of(k: ToolCallKind) -> &'static str {
90	    match k {
91	        ToolCallKind::Function => "function",
92	        ToolCallKind::Custom => "custom",
93	        ToolCallKind::LegacyFunctionCall => "legacy",
94	        ToolCallKind::AnthropicToolUse => "tool_use",
95	        _ => "other",
96	    }
97	}
