99	/// A decided call in the models' terms. A `tool_use` call's arguments are compared as parsed JSON,
100	/// because anthropic-python hands the client the parsed `input`, not the string.
101	pub fn as_model_call(c: &ToolCall) -> ModelCall {
102	    ModelCall {
103	        choice: c.choice,
104	        kind: kind_of(c.kind),
105	        name: c.name.clone(),
106	        arguments: c.arguments.clone(),
107	        parsed: false,
108	    }
109	}
