111	/// Whether `p`, a value parsed from a prefix of some JSON text, can be a prefix of `f`, the value
112	/// of the whole text: strings and numbers may be cut short, objects and arrays may lack members.
113	pub fn json_prefix(p: &Value, f: &Value) -> bool {
114	    match (p, f) {
115	        (Value::Object(a), Value::Object(b)) => a.iter().all(|(k, v)| b.get(k).is_some_and(|w| json_prefix(v, w))),
116	        (Value::Array(a), Value::Array(b)) => a.len() <= b.len() && a.iter().zip(b).all(|(x, y)| json_prefix(x, y)),
117	        (Value::String(a), Value::String(b)) => b.starts_with(a.as_str()),
118	        (Value::Number(a), Value::Number(b)) => b.to_string().starts_with(&a.to_string()),
119	        _ => p == f,
120	    }
121	}
