123	/// Whether a model call's arguments match a decided call's. The decider sees `{}` for empty
124	/// function arguments (the core's rule), so a client's raw `""` matches it. A `parsed` model value
125	/// is compared with the parsed decided string. With `partial` (the snapshot at a raise) the model
126	/// may hold a prefix of the decided arguments: the client stopped reading inside the call.
127	fn arguments_match(mc: &ModelCall, decided: &ModelCall, partial: bool) -> bool {
128	    if mc.kind == "other" {
129	        return true; // the decided form of kind Other is the raw entry
130	    }
131	    if mc.parsed {
132	        let full = if decided.arguments.is_empty() {
133	            Ok(json!({}))
134	        } else {
135	            serde_json::from_str::<Value>(&decided.arguments)
136	        };
137	        let (Ok(full), Ok(got)) = (full, serde_json::from_str::<Value>(&mc.arguments)) else {
138	            return false;
139	        };
140	        return if partial { json_prefix(&got, &full) } else { got == full };
141	    }
142	    if partial {
143	        return decided.arguments.starts_with(&mc.arguments);
144	    }
145	    mc.arguments == decided.arguments || (mc.arguments.is_empty() && decided.arguments == "{}")
146	}
147	
148	/// Invariant I1 as property P1 states it (spec § 2, § 8.1). Every call a client model derives from
149	/// `out` matches a distinct call the decider allowed, by choice, kind, name and arguments
150	/// (arguments are not compared for kind `other`, whose decided form is the raw entry).
151	///
152	/// A model that raises on `out` is an error unless the interceptor dropped a record or took an
153	/// `on_failure` path (`core_failed`), or the client already raises on the upstream bytes `input`:
154	/// a correct interceptor must not make a working client fail. An excused raise is still checked:
155	/// the client may have acted on calls before it raised, so every call in its snapshot must be a
156	/// decided, allowed call, of which it may hold only a prefix if it raised inside the call.
157	pub fn check_i1(format: Format, input: &[u8], out: &[u8], decided: &[(ToolCall, Decision)], core_failed: bool) -> Result<(), String> {
158	    let allowed: Vec<ModelCall> = decided.iter().filter(|(_, d)| d.is_allow()).map(|(c, _)| as_model_call(c)).collect();
159	    let show = || String::from_utf8_lossy(out).into_owned();
160	    for (model, run) in runners(format) {
161	        let r = run(out);
162	        let partial = match &r.error {
163	            None => false,
164	            Some(_) if core_failed || run(input).error.is_some() => true,
165	            Some(e) => return Err(format!("{model} raised on the output: {e}\n{}", show())),
166	        };
167	        let mut left = allowed.clone();
168	        for mc in r.calls {
169	            let hit = left
170	                .iter()
171	                .position(|a| a.choice == mc.choice && a.kind == mc.kind && a.name == mc.name && arguments_match(&mc, a, partial));
172	            match hit {
173	                Some(i) => {
174	                    left.remove(i);
175	                }
176	                None => return Err(format!("{model} runs an undecided or blocked call {mc:?}\nallowed: {allowed:?}\n{}", show())),
177	            }
178	        }
179	    }
180	    Ok(())
181	}
