183	// ---- SSE decoders ------------------------------------------------------------------------------
184	
185	/// One dispatched SSE event.
186	#[derive(Debug, Clone, PartialEq, Eq)]
187	pub struct Sse {
188	    pub event: Option<String>,
189	    pub data: String,
190	}
191	
192	/// Lines split at CRLF, CR or LF; the last element is the unterminated rest (maybe empty).
193	fn lines(bytes: &[u8]) -> (Vec<&[u8]>, &[u8]) {
194	    let mut out = Vec::new();
195	    let mut start = 0;
196	    let mut i = 0;
197	    while i < bytes.len() {
198	        match bytes[i] {
199	            b'\n' => {
200	                out.push(&bytes[start..i]);
201	                start = i + 1;
202	            }
203	            b'\r' => {
204	                out.push(&bytes[start..i]);
205	                if bytes.get(i + 1) == Some(&b'\n') {
206	                    i += 1;
207	                }
208	                start = i + 1;
209	            }
210	            _ => {}
211	        }
212	        i += 1;
213	    }
214	    (out, &bytes[start..])
215	}
216	
217	/// The `SSEDecoder` of openai-python and anthropic-python: lines split at CR, LF and CRLF, each
218	/// line decoded as strict UTF-8 (a bad byte raises), no BOM handling, a dispatch on a blank line
219	/// whenever an event name, data, an id or a retry was seen (so `event:` without `data:` dispatches
220	/// an empty data string), and no dispatch at the end of the stream without a blank line.
221	/// SOURCE: openai-python 3.40.0, src/openai/_streaming.py SSEDecoder.decode and
222	/// _SSELineDecoder; anthropic-python 2.3.0, src/anthropic/_streaming.py SSEDecoder.
223	pub fn py_events(bytes: &[u8]) -> Result<Vec<Sse>, String> {
224	    let (ls, rest) = lines(bytes);
225	    let mut out = Vec::new();
226	    let (mut event, mut data, mut last_id, mut retry): (Option<String>, Vec<String>, Option<String>, Option<i64>) = (None, Vec::new(), None, None);
227	    for raw in ls {
228	        let line = std::str::from_utf8(raw).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
229	        if line.is_empty() {
230	            if event.as_deref().is_none_or(str::is_empty) && data.is_empty() && last_id.as_deref().is_none_or(str::is_empty) && retry.is_none() {
231	                continue;
232	            }
233	            out.push(Sse {
234	                event: event.take(),
235	                data: data.join("\n"),
236	            });
237	            data.clear();
238	            retry = None;
239	            continue;
240	        }
241	        if line.starts_with(':') {
242	            continue;
243	        }
244	        let (name, value) = match line.find(':') {
245	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
246	            None => (line, ""),
247	        };
248	        match name {
249	            "event" => event = Some(value.to_owned()),
250	            "data" => data.push(value.to_owned()),
251	            "id" if !value.contains('\0') => last_id = Some(value.to_owned()),
252	            "retry" => retry = value.parse().ok().or(retry),
253	            _ => {}
254	        }
255	    }
256	    std::str::from_utf8(rest).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
257	    Ok(out)
258	}
