260	/// openai-node's `SSEDecoder` behind `LineDecoder` and a `TextDecoder`: lossy UTF-8 with the BOM
261	/// stripped, lines split at CR, LF and CRLF, `event` and `data` fields only, a dispatch on a blank
262	/// line when an event name or a data line was seen, and a flush of the pending event at the end.
263	/// SOURCE: openai-node <not pinned: modelled only>, src/core/streaming.ts SSEDecoder.
264	pub fn node_events(bytes: &[u8]) -> Vec<Sse> {
265	    let text = String::from_utf8_lossy(bytes);
266	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text);
267	    let (ls, rest) = lines(text.as_bytes());
268	    let mut all: Vec<&[u8]> = ls;
269	    if !rest.is_empty() {
270	        all.push(rest);
271	    }
272	    let mut out = Vec::new();
273	    let (mut event, mut data): (Option<String>, Vec<String>) = (None, Vec::new());
274	    let dispatch = |event: &mut Option<String>, data: &mut Vec<String>, out: &mut Vec<Sse>| {
275	        if event.as_deref().is_none_or(str::is_empty) && data.is_empty() {
276	            return;
277	        }
278	        out.push(Sse {
279	            event: event.take(),
280	            data: data.join("\n"),
281	        });
282	        data.clear();
283	    };
284	    for raw in all {
285	        let line = std::str::from_utf8(raw).expect("lossy text is UTF-8");
286	        if line.is_empty() {
287	            dispatch(&mut event, &mut data, &mut out);
288	            continue;
289	        }
290	        if line.starts_with(':') {
291	            continue;
292	        }
293	        let (name, value) = match line.find(':') {
294	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
295	            None => (line, ""),
296	        };
297	        match name {
298	            "event" => event = Some(value.to_owned()),
299	            "data" => data.push(value.to_owned()),
300	            _ => {}
301	        }
302	    }
303	    dispatch(&mut event, &mut data, &mut out);
304	    out
305	}
