307	/// A reference WHATWG SSE splitter, independent of the crate's: (event, data) per record.
308	pub fn records(bytes: &[u8]) -> Vec<(Option<String>, Vec<u8>)> {
309	    let text = String::from_utf8_lossy(bytes);
310	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text).replace("\r\n", "\n").replace('\r', "\n");
311	    let mut out = Vec::new();
312	    let (mut data, mut has, mut event): (Vec<u8>, bool, Option<String>) = (Vec::new(), false, None);
313	    for line in text.split('\n') {
314	        if line.is_empty() {
315	            if has {
316	                data.pop();
317	                if !data.is_empty() {
318	                    out.push((event.take(), std::mem::take(&mut data)));
319	                }
320	            }
321	            data.clear();
322	            has = false;
323	            event = None;
324	            continue;
325	        }
326	        if line.starts_with(':') {
327	            continue;
328	        }
329	        let (name, value) = match line.find(':') {
330	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
331	            None => (line, ""),
332	        };
333	        match name {
334	            "data" => {
335	                data.extend_from_slice(value.as_bytes());
336	                data.push(b'\n');
337	                has = true;
338	            }
339	            "event" => event = Some(value.to_owned()),
340	            _ => {}
341	        }
342	    }
343	    out
344	}
345	
346	pub fn payloads(bytes: &[u8]) -> Vec<Vec<u8>> {
347	    records(bytes).into_iter().map(|(_, d)| d).collect()
348	}
