350	// ---- Python and JavaScript value semantics -----------------------------------------------------
351	
352	fn py_truthy(v: Option<&Value>) -> bool {
353	    match v {
354	        None | Some(Value::Null) => false,
355	        Some(Value::Bool(b)) => *b,
356	        Some(Value::Number(n)) => n.as_f64() != Some(0.0),
357	        Some(Value::String(s)) => !s.is_empty(),
358	        Some(Value::Array(a)) => !a.is_empty(),
359	        Some(Value::Object(o)) => !o.is_empty(),
360	    }
361	}
362	
363	fn js_truthy(v: Option<&Value>) -> bool {
364	    match v {
365	        None | Some(Value::Null) => false,
366	        Some(Value::Bool(b)) => *b,
367	        Some(Value::Number(n)) => n.as_f64() != Some(0.0),
368	        Some(Value::String(s)) => !s.is_empty(),
369	        Some(_) => true,
370	    }
371	}
372	
373	/// A Python `int` (a `bool` is one), or `None` for anything else.
374	fn py_int(v: &Value) -> Option<i64> {
375	    match v {
376	        Value::Bool(b) => Some(i64::from(*b)),
377	        Value::Number(n) => n.as_i64().or_else(|| n.as_u64().map(|_| i64::MAX)),
378	        _ => None,
379	    }
380	}
381	
382	/// `list[idx]` with Python's negative indexing; `None` is an `IndexError`.
383	fn py_get(len: usize, idx: i64) -> Option<usize> {
384	    let len = i64::try_from(len).expect("small");
385	    let pos = if idx < 0 { idx + len } else { idx };
386	    (0..len).contains(&pos).then(|| usize::try_from(pos).expect("in range"))
387	}
388	
389	/// Where `list.insert(idx, x)` puts `x`.
390	fn py_insert_at(len: usize, idx: i64) -> usize {
391	    let l = i64::try_from(len).expect("small");
392	    let pos = if idx < 0 { (idx + l).max(0) } else { idx.min(l) };
393	    usize::try_from(pos).expect("clamped")
394	}
395	
396	fn py_scalar(v: &Value) -> bool {
397	    matches!(v, Value::String(_) | Value::Number(_) | Value::Bool(_))
398	}
399	
400	fn has_indexed_entries(v: &Value) -> bool {
401	    matches!(v, Value::Array(a) if a.iter().any(|e| matches!(e, Value::Object(o) if o.contains_key("index"))))
402	}
403	
404	fn py_add_numbers(a: &Value, b: &Value) -> Option<Value> {
405	    let int = |v: &Value| match v {
406	        Value::Bool(x) => Some(i64::from(*x)),
407	        Value::Number(n) => n.as_i64(),
408	        _ => None,
409	    };
410	    let float = |v: &Value| match v {
411	        Value::Bool(x) => Some(f64::from(u8::from(*x))),
412	        Value::Number(n) => n.as_f64(),
413	        _ => None,
414	    };
415	    if !matches!(a, Value::Number(_) | Value::Bool(_)) || !matches!(b, Value::Number(_) | Value::Bool(_)) {
416	        return None;
417	    }
418	    match (int(a), int(b)) {
419	        (Some(x), Some(y)) => Some(json!(x.wrapping_add(y))),
420	        _ => Some(json!(float(a)? + float(b)?)),
421	    }
422	}
