424	// ---- openai-python -----------------------------------------------------------------------------
425	
426	/// openai-python `accumulate_delta`. `index` and `type` are replaced, strings and numbers added,
427	/// dicts merged, indexed lists merged by `list[index]` (Python indexing, `insert` on IndexError).
428	/// A value of a different type is kept, not replaced.
429	/// SOURCE: openai-python 3.40.0, src/openai/lib/streaming/_deltas.py accumulate_delta.
430	fn accumulate_delta(acc: &mut Map<String, Value>, delta: &Map<String, Value>) -> Result<(), String> {
431	    for (k, dv) in delta {
432	        if acc.get(k).is_none_or(Value::is_null) {
433	            if has_indexed_entries(dv) {
434	                acc.insert(k.clone(), Value::Array(Vec::new()));
435	            } else {
436	                acc.insert(k.clone(), dv.clone());
437	                continue;
438	            }
439	        }
440	        if k == "index" || k == "type" {
441	            acc.insert(k.clone(), dv.clone());
442	            continue;
443	        }
444	        let av = acc.get_mut(k).expect("present");
445	        if let Some(sum) = py_add_numbers(av, dv) {
446	            *av = sum;
447	            continue;
448	        }
449	        match (av, dv) {
450	            (Value::String(a), Value::String(b)) => a.push_str(b),
451	            (Value::Object(a), Value::Object(b)) => accumulate_delta(a, b)?,
452	            (Value::Array(a), Value::Array(b)) => {
453	                if a.iter().all(py_scalar) && (!a.is_empty() || !has_indexed_entries(dv)) {
454	                    a.extend(b.iter().cloned());
455	                    continue;
456	                }
457	                for e in b {
458	                    let Value::Object(eo) = e else {
459	                        return Err("TypeError: list delta entry is not a dictionary".into());
460	                    };
461	                    let idx = eo.get("index").ok_or("RuntimeError: list delta entry without `index`")?;
462	                    let idx = py_int(idx).ok_or("TypeError: list delta entry `index` is not an integer")?;
463	                    match py_get(a.len(), idx) {
464	                        Some(p) => {
465	                            let Value::Object(target) = &mut a[p] else { return Err("TypeError: not handled yet".into()) };
466	                            accumulate_delta(target, eo)?;
467	                        }
468	                        None => a.insert(py_insert_at(a.len(), idx), e.clone()),
469	                    }
470	                }
471	            }
472	            _ => {} // different types: the accumulated value is kept
473	        }
474	    }
475	    Ok(())
476	}
