486	/// The tool calls of one accumulated OpenAI message. A `function` body is run as a function call
487	/// whatever `type` says (openai-python appends an unknown type as is, openai-node runs every
488	/// non-`custom` type's `function`); a `custom` body is a custom call; anything else is `other`.
489	fn message_calls(choice: u32, m: &Map<String, Value>) -> Vec<ModelCall> {
490	    let mut out = Vec::new();
491	    if let Some(Value::Array(tc)) = m.get("tool_calls") {
492	        for e in tc {
493	            let Value::Object(e) = e else { continue };
494	            let (kind, name, arguments) = if let Some(Value::Object(f)) = e.get("function") {
495	                ("function", str_or_empty(f.get("name")), str_or_empty(f.get("arguments")))
496	            } else if let Some(Value::Object(c)) = e.get("custom") {
497	                ("custom", str_or_empty(c.get("name")), str_or_empty(c.get("input")))
498	            } else {
499	                ("other", str_or_empty(e.get("type")), Value::Object(e.clone()).to_string())
500	            };
501	            out.push(ModelCall {
502	                choice,
503	                kind,
504	                name,
505	                arguments,
506	                parsed: false,
507	            });
508	        }
509	    }
510	    if let Some(Value::Object(fc)) = m.get("function_call") {
511	        out.push(ModelCall {
512	            choice,
513	            kind: "legacy",
514	            name: str_or_empty(fc.get("name")),
