545	/// ChatCompletionStreamState._accumulate_chunk; src/openai/_streaming.py Stream.__stream__.
546	pub fn run_openai_python(bytes: &[u8]) -> Run {
547	    let mut snap: Option<Vec<Value>> = None;
548	    let calls = |snap: &Option<Vec<Value>>| -> Vec<ModelCall> {
549	        let mut out = Vec::new();
550	        for (i, c) in snap.iter().flatten().enumerate() {
551	            if let Some(Value::Object(m)) = c.get("message") {
552	                out.extend(message_calls(u32::try_from(i).expect("small"), m));
553	            }
554	        }
555	        out
556	    };
557	    let mut step = || -> Result<(), String> {
558	        for sse in py_events(bytes)? {
559	            if sse.data.starts_with("[DONE]") {
560	                break;
561	            }
562	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("JSONDecodeError: {e}"))?;
563	            if let Value::Object(m) = &v
564	                && py_truthy(m.get("error"))
565	            {
566	                return Err("APIError: error record".into());
567	            }
568	            if v.get("object").and_then(Value::as_str) != Some("chat.completion.chunk") {
569	                continue;
570	            }
571	            let Some(Value::Array(choices)) = v.get("choices") else {
572	                return Err("AttributeError: chunk.choices".into());
573	            };
574	            let choices: Vec<&Map<String, Value>> = choices.iter().map(|c| obj(Some(c), "choice")).collect::<Result<_, _>>()?;
575	            let Some(list) = snap.as_mut() else {
576	                let mut list: Vec<Value> = choices.iter().map(|c| Value::Object((*c).clone())).collect();
577	                for c in &choices {
578	                    let idx = py_int(c.get("index").ok_or("AttributeError: choice.index")?).ok_or("TypeError: choice.index")?;
579	                    let pos = py_get(list.len(), idx).ok_or("IndexError: list assignment index out of range")?;
580	                    list[pos] = py_new_choice(c)?;
581	                }
582	                snap = Some(list);
583	                continue;
584	            };
585	            for c in &choices {
586	                let idx = py_int(c.get("index").ok_or("AttributeError: choice.index")?).ok_or("TypeError: list indices must be integers")?;
587	                let pos = match py_get(list.len(), idx) {
588	                    Some(p) => {
589	                        let before = tool_types(&list[p]);
590	                        let Some(Value::Object(m)) = list[p].get_mut("message") else {
591	                            return Err("AttributeError: message".into());
592	                        };
593	                        accumulate_delta(m, obj(c.get("delta"), "choice.delta")?)?;
594	                        let after = tool_types(&list[p]);
595	                        for (i, t) in before.iter().enumerate() {
596	                            if t.as_deref() == Some("function") && after.get(i).and_then(Option::as_deref) != Some("function") {
597	                                return Err("AssertionError: new_tool.type == \"function\"".into());
598	                            }
599	                        }
600	                        p
601	                    }
602	                    None => {
603	                        list.push(py_new_choice(c)?);
604	                        list.len() - 1
605	                    }
606	                };
607	                if let Some(Value::Array(frags)) = c.get("delta").and_then(|d| d.get("tool_calls")) {
608	                    let len = match list[pos].pointer("/message/tool_calls") {
609	                        Some(Value::Array(a)) => a.len(),
610	                        _ => 0,
611	                    };
612	                    for f in frags {
613	                        let i = f.get("index").and_then(py_int).ok_or("TypeError: tool_call_chunk.index")?;
614	                        py_get(len, i).ok_or("IndexError: tool_calls[tool_call_chunk.index]")?;
615	                    }
616	                }
617	            }
618	        }
619	        Ok(())
620	    };
621	    let error = step().err();
622	    Run { calls: calls(&snap), error }
623	}
