671	    let mut step = || -> Result<(), String> {
672	        for sse in node_events(bytes) {
673	            if sse.data == "[DONE]" {
674	                break;
675	            }
676	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("SyntaxError: {e}"))?;
677	            if sse.event.as_deref() == Some("error") || js_truthy(v.get("error")) {
678	                return Err("APIError: error record".into());
679	            }
680	            let Some(Value::Array(cs)) = v.get("choices") else {
681	                return Err("TypeError: chunk.choices is not iterable".into());
682	            };
683	            for c in cs {
684	                let idx = js_index(c.get("index"), 128).ok_or("OpenAIError: invalid choice index")?;
685	                let ch = choices.entry(idx).or_default();
686	                if js_truthy(c.get("finish_reason")) {
687	                    ch.finish = c.get("finish_reason").cloned();
688	                }
689	                let Some(d) = c.get("delta").filter(|d| js_truthy(Some(d))) else { continue };
690	                if js_truthy(d.get("role")) {
691	                    ch.role = d.get("role").cloned();
692	                }
693	                if let Some(f) = d.get("function_call").filter(|f| js_truthy(Some(f))) {
694	                    match &mut ch.function_call {
695	                        Some(s) => {
696	                            if js_truthy(f.get("name")) {
697	                                s.insert("name".into(), f["name"].clone());
698	                            }
699	                            if js_truthy(f.get("arguments")) {
700	                                let prev = s.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default();
701	                                s.insert("arguments".into(), Value::String(prev + &js_string(&f["arguments"])));
702	                            }
703	                        }
704	                        None => ch.function_call = Some(f.as_object().cloned().unwrap_or_default()),
705	                    }
706	                }
707	                let Some(tcs) = d.get("tool_calls").filter(|t| js_truthy(Some(t))) else { continue };
708	                let Value::Array(tcs) = tcs else { return Err("TypeError: tool_calls is not iterable".into()) };
709	                for e in tcs {
710	                    let i = js_index(e.get("index"), 128).ok_or("OpenAIError: invalid tool call index")?;
711	                    let t = ch.tools.entry(i).or_default();
712	                    if js_truthy(e.get("id")) {
713	                        t.id = e.get("id").cloned();
714	                    }
715	                    if js_truthy(e.get("type")) {
716	                        t.ty = e.get("type").cloned();
717	                    }
718	                    if let Some(cu) = e.get("custom").filter(|x| js_truthy(Some(x))) {
719	                        let s = t.custom.get_or_insert_with(|| (cu.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
720	                        if js_truthy(cu.get("name")) {
721	                            s.0 = cu["name"].clone();
722	                        }
723	                        if js_truthy(cu.get("input")) {
724	                            s.1.push_str(&js_string(&cu["input"]));
725	                        }
726	                    }
727	                    if let Some(f) = e.get("function").filter(|x| js_truthy(Some(x))) {
728	                        let s = t.function.get_or_insert_with(|| (f.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
729	                        if js_truthy(f.get("name")) {
730	                            s.0 = f["name"].clone();
731	                        }
732	                        if let Some(a) = f.get("arguments").filter(|a| !a.is_null()) {
733	                            s.1.push_str(&js_string(a));
734	                        }
735	                    }
736	                }
737	            }
738	        }
739	        Ok(())
740	    };
741	    let mut error = step().err();
742	    let mut calls = Vec::new();
743	    for (idx, ch) in &choices {
744	        let choice = u32::try_from(*idx).expect("below 128");
745	        if error.is_none() && ch.finish.is_none() {
746	            error = Some(format!("OpenAIError: missing finish_reason for choice {idx}"));
747	        }
748	        if error.is_none() && ch.role.is_none() {
749	            error = Some(format!("OpenAIError: missing role for choice {idx}"));
750	        }
751	        for t in ch.tools.values() {
752	            let custom = t.ty.as_ref().and_then(Value::as_str) == Some("custom");
753	            if error.is_none() && t.ty.is_none() {
754	                error = Some("OpenAIError: missing tool_calls[].type".into());
755	            }
756	            let (kind, body) = if custom { ("custom", &t.custom) } else { ("function", &t.function) };
757	            match body {
758	                Some((name, arguments)) => calls.push(ModelCall {
759	                    choice,
760	                    kind,
761	                    name: js_string(name),
762	                    arguments: arguments.clone(),
763	                    parsed: false,
764	                }),
765	                None if error.is_none() => error = Some(format!("OpenAIError: missing tool_calls[].{kind}.name")),
766	                None => {}
767	            }
768	        }
769	        if let Some(fc) = &ch.function_call {
770	            if error.is_none() && (fc.get("arguments").is_none_or(Value::is_null) || !js_truthy(fc.get("name"))) {
771	                error = Some("OpenAIError: missing function_call.name or .arguments".into());
772	            }
773	            calls.push(ModelCall {
774	                choice,
775	                kind: "legacy",
776	                name: fc.get("name").map(js_string).unwrap_or_default(),
777	                arguments: fc.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default(),
778	                parsed: false,
779	            });
780	        }
781	    }
782	    Run { calls, error }
783	}
