792	/// LangChain `merge_dicts` on two flat dicts: `None` on the left is replaced, `None` on the right
793	/// ignored, strings concatenated except an equal `id`, equal values kept, a type change raises.
794	/// SOURCE: langchain-core <not pinned: modelled only>, langchain_core/utils/_merge.py merge_dicts.
795	fn lc_merge_dicts(left: &mut Map<String, Value>, right: &Map<String, Value>) -> Result<(), String> {
796	    for (k, rv) in right {
797	        let Some(lv) = left.get_mut(k) else {
798	            left.insert(k.clone(), rv.clone());
799	            continue;
800	        };
801	        if lv.is_null() && !rv.is_null() {
802	            *lv = rv.clone();
803	            continue;
804	        }
805	        if rv.is_null() || *lv == *rv && !lv.is_string() {
806	            continue;
807	        }
808	        let same_type = std::mem::discriminant(lv) == std::mem::discriminant(rv) && (lv.is_i64() || lv.is_u64()) == (rv.is_i64() || rv.is_u64());
809	        if !same_type {
810	            return Err(format!("TypeError: additional_kwargs[{k:?}] already exists with a different type"));
811	        }
812	        match (lv, rv) {
813	            (Value::String(l), Value::String(r)) => {
814	                if !(k == "id" && l == r) {
815	                    l.push_str(r);
816	                }
817	            }
818	            (Value::Object(l), Value::Object(r)) => lc_merge_dicts(l, r)?,
819	            (Value::Number(l), Value::Number(r)) if k != "index" => {
820	                *l = py_add_numbers(&Value::Number(l.clone()), &Value::Number(r.clone()))
821	                    .and_then(|v| v.as_number().cloned())
822	                    .ok_or("TypeError")?;
823	            }
824	            (Value::Number(l), Value::Number(r)) => *l = r.clone(), // `index` is replaced
825	            (Value::Array(l), Value::Array(r)) => l.extend(r.iter().cloned()),
826	            _ => return Err(format!("TypeError: unsupported type for {k:?}")),
827	        }
828	    }
829	    Ok(())
830	}
