866	                let choice = obj(Some(choice), "choice")?;
867	                let delta = choice.get("delta").ok_or("KeyError: 'delta'")?;
868	                if delta.is_null() {
869	                    continue;
870	                }
871	                let delta = obj(Some(delta), "delta")?;
