942	                choice: 0,
943	                kind: "function",
944	                name: str_or_empty(e.get("name")),
945	                arguments: args.to_string(),
946	                parsed: true,
947	            })
948	        })
949	        .collect();
950	    if let Some(Value::Object(fc)) = kwargs.get("function_call") {
951	        calls.push(ModelCall {
952	            choice: 0,
953	            kind: "legacy",
954	            name: str_or_empty(fc.get("name")),
955	            arguments: str_or_empty(fc.get("arguments")),
956	            parsed: false,
957	        });
958	    }
959	    Run { calls, error }
