962	/// LangChain `parse_partial_json`: a complete value as is; otherwise unterminated strings are
963	/// closed and open brackets closed in order, then trailing characters are dropped until the text
964	/// parses. A mismatched closing bracket gives `None`. Every candidate the SDK skips with its
965	/// decoder-offset shortcut fails the same way, so dropping one character at a time is equivalent.
966	/// SOURCE: langchain-core <not pinned: modelled only>, langchain_core/utils/json.py parse_partial_json.
967	pub fn lc_parse_partial_json(s: &str) -> Option<Value> {
968	    if let Ok(v) = serde_json::from_str(s) {
969	        return Some(v);
970	    }
971	    let (mut new, mut stack): (Vec<String>, Vec<char>) = (Vec::new(), Vec::new());
972	    let (mut inside, mut escaped) = (false, false);
973	    for ch in s.chars() {
974	        let mut out = ch.to_string();
975	        if inside {
976	            if ch == '"' && !escaped {
977	                inside = false;
978	            } else if ch == '\n' && !escaped {
979	                out = "\\n".to_owned();
980	            } else if ch == '\\' {
981	                escaped = !escaped;
982	            } else {
983	                escaped = false;
984	            }
985	        } else if ch == '"' {
986	            inside = true;
